        """Parses a single SSE wire line. Returns True if [DONE] was received."""
        line = raw_line.strip()
        if not line or line.startswith(":"):
            return False
        if not line.startswith("data:"):
            return False

        payload_str = line[5:].strip()
        if payload_str == "[DONE]":
